flex.button:

    if (navigator.clipboard) {
        navigator.clipboard.writeText($data.copy_input);
    }
    $data.action_feedback = 'Copied to clipboard: ' + $data.copy_input;

📋 Copy Text to Clipboard

div.button:

    if (navigator.wakeLock) {
        navigator.wakeLock.request('screen').then(() => {
            $data.action_feedback = 'Screen Wake Lock Active';
        }).catch(e => {
            $data.action_feedback = 'Wake Lock error: ' + e.message;
        });
    } else {
        $data.action_feedback = 'Wake Lock API not supported in this browser';
    }

☀️ Keep Awake

flex.button:

    if (navigator.geolocation) {
        $data.action_feedback = 'Requesting GPS position...';
        navigator.geolocation.getCurrentPosition(pos => {
            $data.user_coords = {
                latitude: parseFloat(pos.coords.latitude.toFixed(4)),
                longitude: parseFloat(pos.coords.longitude.toFixed(4))
            };
            $data.action_feedback = 'GPS Coordinates Updated (' + pos.coords.latitude.toFixed(2) + ', ' + pos.coords.longitude.toFixed(2) + ')';
        }, err => {
            $data.action_feedback = 'GPS Error: ' + err.message;
        });
    } else {
        $data.action_feedback = 'Geolocation API not supported';
    }

📍 Query Current GPS Location
